type FunctionArgs<F extends Function> = F extends (...args: infer U) => any
  ? U
  : never;

type AnyFunction = (...args: any) => any;

type ComposeFunciton<F extends AnyFunction, G extends AnyFunction> = (
  ...args: FunctionArgs<F>
) => ReturnType<G>;

function composite<
  F extends (...args: any[]) => any,
  G extends (args: ReturnType<F>) => any
>(f: F, g: G): ComposeFunciton<F, G> {
  return (...args: Array<FunctionArgs<F>>): ReturnType<G> => g(f(...args));
}

type FContainer<F extends AnyFunction> = {
  then: <G extends (arg: ReturnType<F>) => any>(
    g: G,
  ) => FContainer<ComposeFunciton<F, G>>;
  apply: (...args: FunctionArgs<F>) => ReturnType<F>;
  unwrap: () => (...args: FunctionArgs<F>) => ReturnType<F>;
};

function id<F extends AnyFunction>(f: F): FContainer<F> {
  return {
    then: <G extends (args: ReturnType<F>) => any>(
      g: G,
    ): FContainer<ComposeFunciton<F, G>> => id(composite(f, g)),
    apply: (...args: Array<FunctionArgs<F>>) => f(...args),
    unwrap: () => f,
  };
}

function add(a: number, b: number): number {
  return a + b;
}

function increment(v: number): number {
  return v + 1;
}

function toString(v: number): string {
  return `${v}`;
}

const b1 = composite(add, increment);
console.log(b1(1, 2)); // 4

// const b2 = composite(toString, add); // type error

const a1 = id(add).then(increment).then(toString).apply(1, 2);
console.log(a1); // '4'

const a2 = id(add).unwrap();
console.log(a2(1, 2)); // 3

const a3 = id(add).then(increment).unwrap();
console.log(a3(1, 2)); // 4

